-- Le voci aggiunte a mano dal pannello (origine=manuale) NON vengono toccate.
-- ============================================================================
BEGIN;

-- 1) via i contenuti ACEA e il vecchio import
DELETE FROM procedura WHERE origine = 'sync' OR brand = '';
DELETE FROM offerta   WHERE origine = 'sync' OR brand = '';
