-- 2) procedure e risposte (29)
INSERT INTO procedura (id, brand, titolo, sottotitolo, etichetta, keywords, tipo, risposta, url, blocchi, origine, attiva, sort_order) VALUES (
  'plenitude:regole', 'plenitude', 'Cosa possiamo vendere', 'Clienti, operazioni e firma ammessi sul brand Plenitude. Controllali prima di aprire la trattativa.', 'Prima di vendere',
  'possiamo, vendere, clienti, operazioni, firma, ammessi, brand, controllali, prima, aprire, trattativa, ammesse', 'blocchi', '', '', U&'[{"tipo":"tabella","titolo":"Operazioni ammesse","colonne":["Operazione","Luce","Gas"],"righe":[["Switch (cambio fornitore)","\2705 S\00ec","\2705 S\00ec"],["Switch con voltura","\2705 S\00ec","\274c No"],["Subentro","\274c No","\274c No"],["Prima attivazione / nuovo allaccio","\274c No","\274c No"],["Condomini","\274c No","\274c No"]]},{"tipo":"nota","testo":"<strong>Subentri e prime attivazioni non si possono fare</strong>, n\00e9 luce n\00e9 gas: si lavorano solo forniture gi\00e0 attive con un altro fornitore (switch, e per la luce switch con voltura)."},{"tipo":"lista","titolo":"Clienti","voci":["<strong>Domestici</strong>: abitazione e locali annessi, luce fino a 15 kW di potenza impegnata. Box e cantine con contatore separato vanno su <strong>Flexi Pertinenze</strong>.","<strong>Business</strong>: partite IVA in bassa tensione. Le Trend Business valgono fino a <strong>30.000 kWh/anno</strong> di luce e <strong>5.000 Smc/anno</strong> di gas.","Le offerte regolate (PLACET, tutela vulnerabilit\00e0 gas) e Trend Casa Plus (solo con fotovoltaico in convenzione) non sono nel listino della rete."]},{"tipo":"lista","titolo":"Firma","voci":["Contratto firmato dal cliente sul tablet con la <strong>firma grafometrica</strong>.","Dopo la firma il contratto va in <strong>check call</strong>, che ha sostituito il check DOI: <strong>se il cliente non risponde il contratto va in KO</strong>. Vedi la procedura \201cCheck call\201d."]},{"tipo":"nota","testo":"Sconto domiciliazione: proponi sempre l\2019addebito SEPA. Sulle Fixa Time e su Flexi Pertinenze vale <strong>-5% sul prezzo di luce e gas</strong>, sulle Trend Casa -1 \20ac/mese. Chiedi sempre l\2019ultima bolletta: servono POD/PDR, potenza, consumi annui e, per il business, la partita IVA. Sulle Trend Business serve l\2019IBAN di un conto corrente per l\2019addebito SEPA obbligatorio."}]'::jsonb, 'sync', TRUE, 0);
INSERT INTO procedura (id, brand, titolo, sottotitolo, etichetta, keywords, tipo, risposta, url, blocchi, origine, attiva, sort_order) VALUES (
  'plenitude:checkcall', 'plenitude', 'Check call: se il cliente non risponde il contratto va in KO', 'Tutti i contratti di switch (SWIN) passano dalla check call di Plenitude. Sostituisce il check DOI.', 'Dopo la firma',
  'check, call, cliente, risponde, contratto, tutti, contratti, switch, swin, passano, sostituisce, dopo, firma, funziona', 'blocchi', '', '', U&'[{"tipo":"nota","testo":"\26a0\fe0f <strong>La check call \00e8 BLOCCANTE.</strong> Se il cliente non risponde alle chiamate, <strong>il contratto cade (KO)</strong> e la vendita \00e8 persa. Va avvisato prima di salutarlo."},{"tipo":"tabella","titolo":"Come funziona","colonne":["Voce","Dettaglio"],"righe":[["Contratti coinvolti","Il <strong>100% degli switch (SWIN)</strong>, luce e gas"],["Numero che chiama","<strong>02 4441 8755</strong>"],["Tentativi","<strong>10 chiamate</strong>, una ogni 3 ore"],["Orari","Dal luned\00ec al venerd\00ec <strong>dalle 9 alle 20</strong>, pi\00f9 il <strong>sabato mattina</strong>"],["Durata massima","La verifica pu\00f2 durare <strong>3 \2013 4 giorni</strong>: dopo l\2019ultimo tentativo senza risposta il contratto va in KO"],["Avviso all\2019operatore","A fine firma SalesUp avvisa l\2019operatore che il contratto andr\00e0 in verifica con check call"]]},{"tipo":"passi","titolo":"Cosa dire al cliente prima che vada via","voci":["Spiegagli che nei prossimi giorni lo chiamer\00e0 Plenitude per confermare il contratto, e che <strong>senza la sua risposta il contratto non parte</strong>.","Fagli <strong>salvare in rubrica il numero 02 4441 8755</strong> (es. \201cPlenitude conferma contratto\201d), cos\00ec non lo scambia per una chiamata commerciale.","Controlla che il <strong>numero di cellulare</strong> inserito sul contratto sia giusto e raggiungibile.","Ricordagli gli orari: luned\00ec \2013 venerd\00ec 9-20 e sabato mattina, ogni 3 ore."]},{"tipo":"info","testo":"Se il cliente ti dice che non riesce a rispondere o che il contratto \00e8 andato in KO, avvisa subito il tuo referente commerciale."}]'::jsonb, 'sync', TRUE, 1);
INSERT INTO procedura (id, brand, titolo, sottotitolo, etichetta, keywords, tipo, risposta, url, blocchi, origine, attiva, sort_order) VALUES (
  'plenitude:deposito', 'plenitude', 'Bollettino e deposito cauzionale', 'Vale per tutte le offerte. Il deposito (anticipo sui consumi) si addebita solo se il cliente paga con bollettino postale.', 'Pagamenti',
  'bollettino, deposito, cauzionale, vale, tutte, offerte, anticipo, consumi, addebita, solo, cliente, paga, postale, pagamenti', 'blocchi', '', '', U&'[{"tipo":"info","testo":"Con <strong>addebito SEPA su conto corrente</strong> non c\2019\00e8 nessun deposito cauzionale e in pi\00f9 il cliente ha lo <strong>sconto domiciliazione</strong> (-5% su Fixa Time e Flexi Pertinenze, -1 \20ac/mese su Trend Casa). Proponilo sempre prima del bollettino."},{"tipo":"tabella","titolo":"Luce \00b7 deposito con bollettino postale","colonne":["Potenza e uso","Deposito cauzionale","Bollette all\2019anno"],"righe":[["3 kW \00b7 uso domestico","15,48 \20ac","6"],["4,5 kW \00b7 uso domestico","23,22 \20ac","6"],["Fino a 15 kW \00b7 uso non domestico","7,75 \20ac/kW (15 kW = 116,25 \20ac)","6"],["Da 15 a 100 kW \00b7 uso non domestico","10,33 \20ac/kW (100 kW = 1.033,00 \20ac)","12"],["Oltre 100 kW \00b7 uso non domestico","11,88 \20ac/kW (300 kW = 3.564,00 \20ac)","12"]]},{"tipo":"lista","titolo":"Come si calcola la luce domestica","voci":["Le CTE domestiche indicano <strong>5,16 \20ac per ogni kW</strong> di potenza impegnata: 3 kW = 15,48 \20ac, 4,5 kW = 23,22 \20ac, 6 kW = 30,96 \20ac.","Si addebita nella prima bolletta e torna al cliente, senza che lo chieda, nella bolletta di chiusura."]},{"tipo":"tabella","titolo":"Gas \00b7 deposito con bollettino postale","colonne":["Consumo annuo","Deposito cauzionale","Bollette all\2019anno"],"righe":[["Fino a 100 Smc","30,00 \20ac","3"],["101 \2013 500 Smc","30,00 \20ac","3"],["501 \2013 1.500 Smc","90,00 \20ac","6"],["1.501 \2013 5.000 Smc","150,00 \20ac","6"],["5.001 \2013 11.000 Smc","200,00 \20ac","12"],["11.001 \2013 25.000 Smc","450,00 \20ac","12"],["25.001 \2013 50.000 Smc","1.000,00 \20ac","12"],["50.001 \2013 100.000 Smc","1.500,00 \20ac","12"],["100.001 \2013 200.000 Smc","3.000,00 \20ac","12"]]},{"tipo":"nota","testo":"Cliente che ha gi\00e0 una fornitura luce e/o gas e <strong>non ha mai attivato l\2019addebito</strong> su conto corrente bancario o postale: se lo attiva pu\00f2 <strong>recuperare subito il deposito cauzionale</strong> gi\00e0 versato, pi\00f9 gli interessi legali maturati. \00c8 un ottimo argomento per convincerlo a domiciliare."},{"tipo":"info","testo":"Sulle <strong>Trend Business</strong> l\2019addebito SEPA \00e8 obbligatorio, quindi il bollettino non si pu\00f2 scegliere. Valori del gas in vigore dal 13 ottobre 2014."}]'::jsonb, 'sync', TRUE, 2);
INSERT INTO procedura (id, brand, titolo, sottotitolo, etichetta, keywords, tipo, risposta, url, blocchi, origine, attiva, sort_order) VALUES (
  'plenitude:credenziali', 'plenitude', 'Credenziali e primo accesso', U&'Dalla mail con l\2019utenza Plenitude al cambio password. Va fatto entro 48 ore.', 'Passo 1',
  'credenziali, primo, accesso, mail, utenza, cambio, password, fatto, entro, passo, ricezione, tipo', 'blocchi', '', '', U&'[{"tipo":"passi","titolo":"Ricezione e cambio password","voci":["Attendi la mail da <strong>noreply.identity.governance@eni.com</strong> con le credenziali Plenitude (formato <strong>nome.cognome@partner.eniplenitude.com</strong>). Non configurare il tablet prima di averla ricevuta.","Salva lo <strong>username</strong> indicato nella mail: serve per tutti i sistemi Plenitude.","Clicca il link <strong>\201cMicrosito di autenticazione\201d</strong> nella mail: si apre il browser del tablet.","Inserisci la password provvisoria ricevuta, poi la nuova password scelta da te, e premi <strong>Cambio Password</strong>."]},{"tipo":"nota","testo":"Il cambio password va fatto <strong>entro 48 ore</strong> dalla mail. Dopo, il sistema risponde che le credenziali non sono riconosciute e serve un reset dall\2019Help Desk (800 180 801)."},{"tipo":"tabella","titolo":"Che tipo di utenza hai","colonne":["Username","A chi \00e8 assegnato"],"righe":[["COFR\2026","Operatore di negozio"],["CO\2026","Teleseller inbound"],["EXT\2026","Chi lavora in un flagship"],["DAG\2026","Tutti gli altri casi"]]},{"tipo":"info","testo":"Entro 48 ore dalla prima mail ne arriva una seconda con l\2019abilitazione a <strong>SalesUp (D365)</strong>. Se hai gi\00e0 un\2019utenza Plenitude attiva e ricordi la password, non devi cambiarla."}]'::jsonb, 'sync', TRUE, 3);
INSERT INTO procedura (id, brand, titolo, sottotitolo, etichetta, keywords, tipo, risposta, url, blocchi, origine, attiva, sort_order) VALUES (
  'plenitude:salesup', 'plenitude', 'SalesUp e Microsoft Authenticator', U&'Primo accesso al portale contratti e attivazione dell\2019autenticazione a due fattori (MFA).', 'Passo 2',
  'salesup, microsoft, authenticator, primo, accesso, portale, contratti, attivazione, dell, autenticazione, fattori, passo, apri, configurazione', 'blocchi', '', '', U&'[{"tipo":"link","titolo":"Apri SalesUp","testo":"egl-ev-p1.crm4.dynamics.com \00b7 meglio con Edge o Chrome","href":"https://egl-ev-p1.crm4.dynamics.com/"},{"tipo":"passi","titolo":"Accesso e configurazione MFA","voci":["Sul tablet apri SalesUp, inserisci <strong>nome.cognome@partner.eniplenitude.com</strong> e premi <strong>Avanti</strong>; poi inserisci la nuova password e premi <strong>Accedi</strong>.","Il sistema avvisa che va configurata la protezione dell\2019account: premi <strong>Avanti</strong>.","Installa <strong>Microsoft Authenticator sul tuo smartphone</strong> (non sul tablet!), aprilo e scegli di aggiungere un account aziendale.","Sul tablet premi <strong>Avanti</strong>: compare un QR code (se non lo vedi, clicca \201cMostra il codice a matrice\201d). Scansionalo con lo smartphone e premi <strong>Avanti</strong>.","Il tablet mostra un codice numerico: scrivilo nell\2019app sullo smartphone e conferma. Sul tablet compare \201cLa notifica \00e8 stata approvata\201d: premi <strong>Avanti</strong>.","Rientra in SalesUp con credenziali e codice, scegli il mercato <strong>Residenziale</strong> e premi <strong>Salva</strong> in fondo alla pagina."]},{"tipo":"lista","titolo":"Se compare una finestra in pi\00f9","voci":["Pop-up grigio che chiede di nuovo utente e password: scrivi <strong>ENINET\\\\</strong> seguito dalla tua utenza (es. ENINET\\\\COXXXX) e la password abituale. Usa sempre la CO anche se hai un\2019utenza EXT.","\201cVuoi restare connesso?\201d: rispondi <strong>S\00ec</strong>.","Pagina con il pulsante <strong>\201cAccedi utilizzando Plenitude Login\201d</strong>: cliccalo, senza inserire altre credenziali."]},{"tipo":"nota","testo":"Se usi gi\00e0 Microsoft Authenticator con un altro account aziendale, <strong>contatta l\2019Help Desk prima</strong> di configurare il tablet. Se dopo il QR code compare un errore, controlla di aver scritto nome.cognome@partner.eniplenitude.com; se \00e8 giusto, chiama l\2019Help Desk."}]'::jsonb, 'sync', TRUE, 4);
INSERT INTO procedura (id, brand, titolo, sottotitolo, etichetta, keywords, tipo, risposta, url, blocchi, origine, attiva, sort_order) VALUES (
  'plenitude:firma', 'plenitude', 'App firma grafometrica', U&'Installazione sul tablet dell\2019app per far firmare i contratti.', 'Passo 3',
  'firma, grafometrica, installazione, tablet, dell, firmare, contratti, passo, scarica, apperian, fornito, regole', 'blocchi', '', '', U&'[{"tipo":"link","titolo":"Scarica dal MAM Plenitude (Apperian)","testo":"eni.ease.apperian.eu \00b7 Android e iOS","href":"https://eni.ease.apperian.eu/download_app.php?org=HqYpSGCfAfIaD62Kao1SeA"},{"tipo":"passi","titolo":"Tablet non fornito da Plenitude","voci":["Apri il link qui sopra dal tablet: installa prima il software di <strong>Mobile Application Management (Apperian)</strong> di Plenitude.","Segui le istruzioni a schermo (sono diverse per Android e iOS e possono chiedere di autorizzare l\2019installazione).","Apri Apperian e registrati al servizio Eni Plenitude con la tua <strong>utenza e password Plenitude</strong>.","Dal catalogo installa l\2019<strong>app di firma grafometrica</strong>."]},{"tipo":"lista","titolo":"Regole d\2019uso del tablet","voci":["Usa il tablet <strong>solo</strong> per i sistemi e le app Plenitude.","Accedi a SalesUp solo con l\2019email nome.cognome@partner.eniplenitude.com.","Rispetta l\2019ordine: credenziali \2192 SalesUp e MFA \2192 app di firma."]}]'::jsonb, 'sync', TRUE, 5);
INSERT INTO procedura (id, brand, titolo, sottotitolo, etichetta, keywords, tipo, risposta, url, blocchi, origine, attiva, sort_order) VALUES (
  'plenitude:problemi', 'plenitude', 'A chi segnalare un problema', 'Ogni tipo di problema ha il suo canale: scegli quello giusto per avere risposta prima.', 'Assistenza',
  'segnalare, problema, ogni, tipo, canale, scegli, giusto, avere, risposta, prima, assistenza', 'blocchi', '', '', U&'[{"tipo":"tabella","titolo":"Canale per tipo di problema","colonne":["Problema","Esempi","Chi contattare"],"righe":[["Accesso e strumenti","Reset password, password scaduta dopo 48 ore, MFA/Authenticator, installazione firma grafometrica, primo accesso a SalesUp","Help Desk 800 180 801"],["Anomalie di SalesUp","Non riesci pi\00f9 ad accedere, indirizzo non presente nello stradario, dati cliente non modificabili, crash o campi bloccati","Ticket su Service Now (Snow)"],["Offerte e contratti","Dubbi su un\2019offerta, lettura bolletta, stato di un contratto, esito check call, reinserimento firma, pop-up di errore, offerta sbagliata","Referente commerciale E2K"],["Profilo operatore","Dati del profilo non corretti, utenza non riconosciuta","Referente commerciale E2K"]]},{"tipo":"info","testo":"Quando segnali un problema allega sempre <strong>una descrizione chiara e lo screenshot</strong> dell\2019errore."}]'::jsonb, 'sync', TRUE, 6);
INSERT INTO procedura (id, brand, titolo, sottotitolo, etichetta, keywords, tipo, risposta, url, blocchi, origine, attiva, sort_order) VALUES (
  'plenitude:come-leggere', 'plenitude', 'Come leggere le offerte Plenitude', '', 'Offerte',
  'leggere, offerta, prezzo, spread, commercializzazione, sconto, corrispettivo, energia, valore, bolletta, vendita, domiciliazione, bollettino, deposito', 'blocchi', '', '', U&'[{"tipo":"info","titolo":"Corrispettivo energia","testo":"Nelle offerte variabili \00e8 <strong>PUN o PSV + spread</strong> (Plenitude lo chiama \201cContributo al Consumo\201d). Nelle fisse \00e8 un prezzo unico in \20ac/kWh o \20ac/Smc che non cambia per 12 o 24 mesi."},{"tipo":"info","titolo":"Valore CTE e valore in bolletta","testo":"Per la luce la CTE scrive il prezzo <strong>comprese le perdite di rete</strong> (10% in bassa tensione) e subito sotto il valore al netto, che \00e8 quello stampato in bolletta. Esempio Trend Casa: 0,022 in CTE, 0,02 \20ac/kWh in bolletta."},{"tipo":"info","titolo":"Commercializzazione e Vendita","testo":"\00c8 la quota fissa annua per POD o PDR, indipendente dai consumi: 96, 120, 144 o 192 \20ac/anno a seconda dell\2019offerta. Viene addebitata mese per mese."},{"tipo":"info","titolo":"Sconto domiciliazione","testo":"Proponilo sempre: con l\2019addebito SEPA il cliente ha <strong>-5% sul prezzo di luce e gas</strong> sulle Fixa Time e su Flexi Pertinenze, -1 \20ac/mese sulle Trend Casa. Sulle Trend Business il SEPA \00e8 obbligatorio."},{"tipo":"info","titolo":"Bollettino = deposito cauzionale","testo":"Se il cliente paga con <strong>bollettino postale</strong> nella prima bolletta trova il deposito: luce 5,16 \20ac/kW (15,48 \20ac con 3 kW), gas da 30 \20ac in su secondo i consumi. Con l\2019addebito SEPA niente deposito e c\2019\00e8 lo sconto. Tabelle complete in Procedure."},{"tipo":"info","titolo":"Monoraria o bioraria","testo":"Le offerte luce a prezzo fisso hanno anche i prezzi per fascia: <strong>F1</strong> dalle 8 alle 19 dei giorni feriali, <strong>F23</strong> tutte le altre ore. La bioraria si applica solo con contatore che misura per fasce."},{"tipo":"info","titolo":"Validit\00e0 della CTE","testo":"La data \201cvalida fino al\201d \00e8 quella entro cui il contratto va <strong>firmato</strong>. Le CTE di questo listino scadono il 14/10/2026; Fixa Time 24 Smart pu\00f2 chiudere prima per esaurimento."}]'::jsonb, 'sync', TRUE, 7);
INSERT INTO procedura (id, brand, titolo, sottotitolo, etichetta, keywords, tipo, risposta, url, blocchi, origine, attiva, sort_order) VALUES (
  'plenitude:portali', 'plenitude', 'Portali e strumenti Plenitude', '', 'Accessi',
  'portale, accesso, link, strumenti, comparatore, inserimento, salesup, firma, grafometrica, microsoft, authenticator', 'blocchi', '', '', U&'[{"tipo":"link","titolo":"SalesUp","testo":"Portale Plenitude per caricare i contratti (Dynamics 365). Usa Edge o Chrome e accedi con nome.cognome@partner.eniplenitude.com.","href":"https://egl-ev-p1.crm4.dynamics.com/"},{"tipo":"link","titolo":"App firma grafometrica","testo":"Si installa sul tablet dal Mobile Application Management Plenitude (Apperian). Serve per far firmare i contratti.","href":"https://eni.ease.apperian.eu/download_app.php?org=HqYpSGCfAfIaD62Kao1SeA"},{"tipo":"link","titolo":"Microsoft Authenticator","testo":"App per l\2019accesso a due fattori (MFA). Va installata sul tuo smartphone, non sul tablet.","href":"https://play.google.com/store/apps/details?id=com.azure.authenticator"},{"tipo":"link","titolo":"Comparatore Plenitude","testo":"Confronto bolletta e classifica delle offerte Plenitude per risparmio, con preventivo PDF e invio su WhatsApp.","href":"https://comparatoreplenitude.vercel.app/"}]'::jsonb, 'sync', TRUE, 8);
INSERT INTO procedura (id, brand, titolo, sottotitolo, etichetta, keywords, tipo, risposta, url, blocchi, origine, attiva, sort_order) VALUES (
  'sorgenia:residenziale', 'sorgenia', 'Contratto residenziale', 'Dalla verifica creditizia alla firma remota, tutto su Apparound.', 'Domestico',
  'contratto, residenziale, verifica, creditizia, firma, remota, tutto, apparound, domestico, legenda, credit, check, creazione, dell', 'blocchi', '', '', U&'[{"tipo":"passi","titolo":"1 \00b7 Verifica creditizia (su Apparound)","voci":["Da <strong>Offerte per la casa</strong> inserisci i dati del cliente che firmer\00e0: e-mail, telefono, nome, cognome e codice fiscale.","Metti il flag su <strong>informativa privacy</strong> e <strong>informativa SIC</strong>: senza flag la verifica non parte.","Leggi il semaforo e controlla nella tabella qui sotto quali operazioni sono ammesse."]},{"tipo":"tabella","titolo":"Legenda credit check residenziale","colonne":["Semaforo","Switch semplice","Nuovo allaccio","Riattivazione luce","Switch con voltura"],"righe":[["\+01f7e2 Verde","OK","OK","OK","OK"],["\+01f7e1 Giallo / \+01f7e0 Arancione","OK se il cliente \00e8 proprietario e/o legato al contratto business","OK se il cliente \00e8 proprietario","KO","KO"],["\+01f7e3 Viola","OK se il cliente \00e8 proprietario","KO","KO","KO"],["\+01f535 Blu","OK se il cliente \00e8 proprietario","KO","KO","KO"],["\+01f534 Rosso","Blocco automatico","Blocco automatico","Blocco automatico","Blocco automatico"]]},{"tipo":"passi","titolo":"2 \00b7 Creazione dell\2019offerta (agente)","voci":["Inserisci il <strong>codice contratto business</strong> di aggancio: l\2019app verifica che non siano gi\00e0 stati usati i <strong>5 contratti residenziali</strong> previsti per ogni contratto business firmato.","Il codice business va scritto <strong>senza la barra</strong>: 000001/A6 diventa 000001A6.","Il numero di telefono deve essere del cliente: se coincide con quello di un agente non pu\00f2 essere usato per la firma. Il codice fiscale viene controllato anche sulla blacklist Sorgenia.","Si prosegue solo con indirizzo normalizzato (puntatore verde). Poi clicca <strong>Componi offerta</strong>.","Nel configuratore scegli <strong>Dual (luce + gas)</strong>, <strong>Solo energia</strong> o <strong>Solo gas</strong>, completa il carrello e vai avanti."]},{"tipo":"passi","titolo":"3 \00b7 Dati di fornitura e invio al cliente","voci":["<strong>POD</strong>: scegli l\2019operazione tra switch, nuovo allaccio, riattivazione o switch con voltura.","<strong>PDR</strong>: scegli l\2019operazione tra switch, nuovo allaccio o riattivazione, e il tipo di voltura (nessuna, residenziale, business).","Indirizzo: flag \201cresidenziale\201d se coincide con la residenza, altrimenti inseriscilo e premi <strong>Normalizza indirizzo</strong>. Al salvataggio l\2019app verifica se POD o PDR sono gi\00e0 in uso in Sorgenia.","Allega documento d\2019identit\00e0 e fattura, poi <strong>Rendi definitiva</strong> l\2019offerta. Metti il flag per includere le CTE, cos\00ec il cliente le pu\00f2 scaricare prima di firmare.","Con <strong>Vedi / Invia</strong> mandi l\2019offerta al cliente per la firma."]},{"tipo":"passi","titolo":"4 \00b7 Firma del cliente (Interactive Tools)","voci":["Il cliente apre la mail, legge l\2019informativa e si autentica con il cellulare (solo al primo accesso).","Pu\00f2 scaricare offerta e CTE, poi clicca <strong>Prepara contratto</strong>.","Inserisce l\2019IBAN (controllato su formato e ABI/CAB), l\2019eventuale data dello switch con voltura, i consensi privacy, il luogo di firma e gli allegati, poi <strong>Genera contratto</strong>.","Con <strong>Firma contratto</strong> riceve il link di firma remota (IDSIGN): per SMS nella rete fisica, per e-mail nel teleselling.","Dopo la firma riceve il PDF del contratto; su Apparound compare \201cContratto firmato\201d e la pratica passa da sola su <strong>SPACE</strong>."]},{"tipo":"lista","titolo":"Documenti obbligatori","voci":["<strong>Due documenti</strong> tra carta d\2019identit\00e0, codice fiscale, patente e passaporto.","<strong>Fattura</strong> del cliente, non richiesta per riattivazioni, nuovi allacci e switch con voltura luce.","Per riattivazione, nuovo allaccio e switch con voltura: <strong>contratto di locazione, propriet\00e0 o usufrutto, oppure visura catastale</strong>.","Per lo switch con voltura luce: anche la <strong>Dichiarazione di legittimo possesso</strong>.","Se firma un delegato e non l\2019intestatario: il <strong>documento di delega</strong>, da allegare su Apparound e inviare anche al Supporto CCQ."]},{"tipo":"lista","titolo":"Il tuo portafoglio su Apparound","voci":["Stati dell\2019offerta: bozza, definitiva, non firmata, firmata. Le bozze <strong>non contano</strong> nei 5 residenziali per contratto business.","Le offerte definitive o non firmate si possono far scadere con <strong>Forza scadenza offerta</strong>, per liberare posti sul contratto business.","In <strong>Interazioni</strong> vedi accessi del cliente, durata delle sessioni e download di offerta e contratto.","La <strong>Dashboard codici contratto</strong> mostra i codici business disponibili e quanti residenziali sono gi\00e0 agganciati.","Lo stato su SPACE si segue con le istruzioni di pag. 67 del Manuale Utente sul portale agenti LOGOS."]},{"tipo":"info","testo":"Dopo la firma parte la <strong>CCQ</strong>: vedi la procedura dedicata."}]'::jsonb, 'sync', TRUE, 9);
INSERT INTO procedura (id, brand, titolo, sottotitolo, etichetta, keywords, tipo, risposta, url, blocchi, origine, attiva, sort_order) VALUES (
  'sorgenia:business', 'sorgenia', 'Contratto business', 'Verifica della partita IVA su CRI, poi inserimento su Apparound.', 'P. IVA',
  'contratto, business, verifica, partita, inserimento, apparound, procede, documenti, obbligatori', 'blocchi', '', '', U&'[{"tipo":"passi","titolo":"Come si procede","voci":["Controlla il credito della partita IVA su <strong>CRI</strong> (pulsante in alto nella pagina).","\+01f7e2 <strong>Verde</strong>: si procede senza vincoli.","\+01f7e1 <strong>Giallo</strong> o <strong>non censito</strong>: si procede solo con <strong>IBAN / SDD</strong>.","\+01f535 <strong>Blu</strong>: si procede solo con <strong>CTE Blu</strong> (i listini indicati da CRI) e <strong>SDD / IBAN</strong>.","Inserisci il contratto su <strong>Apparound</strong>: firma con OTP via <strong>SMS per Mass Market</strong>, via <strong>e-mail per PMI</strong>."]},{"tipo":"lista","titolo":"Documenti obbligatori","voci":["<strong>Documento d\2019identit\00e0</strong>, patente o passaporto del firmatario.","<strong>Fattura</strong> del cliente, non richiesta per riattivazioni, nuovi allacci e switch con voltura luce.","Per riattivazione, nuovo allaccio e switch con voltura: <strong>contratto di locazione, propriet\00e0 o usufrutto, oppure visura catastale</strong>."]},{"tipo":"info","testo":"La CCQ Digital vale per i contratti <strong>Mass Market</strong>; sui contratti <strong>PMI</strong> non viene fatta."},{"tipo":"nota","testo":"Il credit check \00e8 bloccato ma pensi si possa sbloccare? Scrivi al <strong>Supporto Operation</strong>."}]'::jsonb, 'sync', TRUE, 10);
INSERT INTO procedura (id, brand, titolo, sottotitolo, etichetta, keywords, tipo, risposta, url, blocchi, origine, attiva, sort_order) VALUES (
  'sorgenia:cri', 'sorgenia', U&'Leggere l\2019esito CRI', 'Semafori, fasce di consumo e listini per la verifica creditizia business.', 'Credit check',
  'leggere, esito, semafori, fasce, consumo, listini, verifica, creditizia, business, credit, check, aree, messaggi, senza', 'blocchi', '', '', U&'[{"tipo":"info","testo":"CRI \00e8 la piattaforma Sorgenia per la pre-verifica della solvibilit\00e0 della partita IVA, da PC o da mobile. Inserisci la P. IVA: il semaforo dice se il cliente \00e8 acquisibile e per quale fascia di consumo."},{"tipo":"tabella","titolo":"Fasce di consumo (aree)","colonne":["Area","Luce (MWh/anno)","Gas (migliaia di Smc/anno)"],"righe":[["Area 1","meno di 5","meno di 10"],["Area 2","da 5 a 30","da 10 a 30"],["Area 3","da 30 a 200","da 30 a 100"],["Area 4a","da 200 a 1.000","da 100 a 370"],["Area 4b","da 1.000 a 3.000","da 370 a 1.100"],["Area 4c","da 3.000 in su","da 1.100 in su"]]},{"tipo":"tabella","titolo":"Semafori","colonne":["Esito","Significato"],"righe":[["\+01f7e2 Verde","Credit check OK: nessun vincolo su prodotti, consumi o modalit\00e0 di pagamento."],["\+01f7e1 Giallo","Acquisibile solo con SDD."],["\+01f535 Blu","Acquisibile con SDD e uno dei prodotti indicati da CRI."],["\+01f534 Rosso","Credit check KO: score sotto qualsiasi soglia derogabile."]]},{"tipo":"tabella","titolo":"Messaggi senza semaforo","colonne":["Messaggio","Cosa fare"],"righe":[["Non contrattualizzabile perch\00e9 in blacklist","P. IVA in blacklist per morosit\00e0 pregressa. Non derogabile."],["Non contrattualizzabile","Rating sotto la soglia minima derogabile o eventi negativi: KO."],["Azienda non censita (aree 1-3)","Serve una fattura di massimo 2 mesi prima, azienda costituita da almeno 6 mesi, pagamento SDD."],["Azienda non censita (area 4a)","Chiedi informazioni all\2019AM o all\2019ufficio Sales Development e segnala al credito."],["Azienda non censita (aree 4b e 4c)","Cliente non acquisibile."],["Il cliente \00e8 gi\00e0 attivo","Cliente gi\00e0 in portafoglio Sorgenia."]]},{"tipo":"lista","titolo":"Prodotti indicati con semaforo blu","voci":["Area 1: PCV23, PCV18, PCV15, QVD 6.6, QVD 8.","Area 2: PCV23, PCV18, PCV15, CRL1, CRL2, CRL3.","Area 3: CRL1, CRL2, CRL3, CRL4, CRL5.","Se esce <strong>CRL0</strong> il cliente non si pu\00f2 acquisire.","Area 4b: acquisibile in 4b con SDD e in 4a con qualsiasi modalit\00e0 di pagamento. Area 4c: in 4c e 4b con SDD, in 4a con qualsiasi modalit\00e0."]},{"tipo":"tabella","titolo":"Listini in ordine graduale","colonne":["Area","Luce","Gas"],"righe":[["Area 1","CRL0, MMPCV15, MMPCV18, MMPCV23","CRL0, MMQVD6.6, MMQVD8"],["Area 2","CRL0, MMPCV15, MMPCV18, MMPCV23","CRL4, CRL3, CRL2, CRL1, CRL0"],["Area 3","CRL6, CRL4, CRL5, CRL3, CRL2, CRL1, CRL0","CRL4, CRL3, CRL2, CRL1, CRL0"],["Area 4","CRL6, CRL4, CRL5, CRL3, CRL2, CRL1","CRL4, CRL3, CRL2, CRL1"]]},{"tipo":"lista","titolo":"Agevolazioni segnalate da CRI (in base al codice ATECO)","voci":["Luce: possibile IVA ridotta; possibile \201cenergivoro\201d se consuma almeno 1 GWh/anno.","Gas: possibile IVA ridotta; possibile accisa ridotta per usi industriali.","Usale in trattativa come valore aggiunto: il cliente pu\00f2 avere da 0 a 4 segnalazioni. Per le pratiche scrivi all\2019ufficio Agevolazioni fiscali."]}]'::jsonb, 'sync', TRUE, 11);
INSERT INTO procedura (id, brand, titolo, sottotitolo, etichetta, keywords, tipo, risposta, url, blocchi, origine, attiva, sort_order) VALUES (
  'sorgenia:ccq', 'sorgenia', U&'CCQ \00b7 conferma del contratto', 'CCQ Digital, FAST CCQ e CCQ tradizionale: cosa succede dopo la firma.', 'Dopo la firma',
  'conferma, contratto, digital, fast, tradizionale, succede, dopo, firma, flusso, casi, particolari, stati, portafoglio, apparound', 'blocchi', '', '', U&'[{"tipo":"info","testo":"La CCQ si fa su tutti i contratti <strong>residenziali</strong> e <strong>Mass Market</strong>. Sui contratti <strong>PMI</strong> non si fa."},{"tipo":"passi","titolo":"Il flusso","voci":["<strong>CCQ Digital</strong>: dopo la firma il cliente riceve una mail da no.reply@sorgenia.it con oggetto \201cCONFERMA CONTRATTO\201d. Inserisce il numero usato per l\2019OTP, rivede dati di fornitura, dati anagrafici, prodotti e data/ora della firma, e sceglie \201cS\00ec, confermo\201d oppure \201cNo, voglio essere ricontattato\201d.","Se non conferma, alle <strong>18:00</strong> riceve una mail di promemoria con il link diretto.","Con \201cS\00ec, confermo\201d il contratto passa su SPACE. Con \201cNo, voglio essere ricontattato\201d o con il link scaduto segue il flusso standard.","<strong>FAST CCQ</strong>: il giorno dopo il cliente riceve un messaggio di preavviso e poi la chiamata. Se non risponde si riprova il giorno successivo; il 3\00b0 giorno la pratica entra su SPACE.","<strong>CCQ tradizionale</strong>: se il cliente resta irreperibile o la FAST va in KO, la CCQ va organizzata con il Supporto CCQ. Senza risposta il contratto va in KO."]},{"tipo":"nota","testo":"Il link della CCQ Digital scade alle <strong>ore 23:59 del giorno stesso dell\2019inserimento</strong>: dopo quell\2019ora lo stato diventa \201cInvalidato\201d e parte la CCQ standard, con la FAST CCQ il giorno dopo. Fai confermare il cliente subito, prima che lasci il negozio."},{"tipo":"lista","titolo":"Casi particolari","voci":["<strong>Ultimo giorno del mese</strong>: i contratti vanno direttamente su SPACE e fanno solo la CCQ tradizionale, senza Digital n\00e9 FAST.","<strong>Primi 7 giorni del mese</strong> (rete fisica): c\2019\00e8 la domanda in pi\00f9 \201cL\2019agente era presente fisicamente?\201d. Se il cliente sceglie \201cNo, voglio essere ricontattato\201d il contratto non si pu\00f2 confermare.","<strong>Delegato</strong> (solo residenziale): si pu\00f2 indicare che chi firma non \00e8 l\2019intestatario. La delega va allegata su Apparound e inviata al Supporto CCQ."]},{"tipo":"tabella","titolo":"Stati CCQ Digital nel portafoglio Apparound","colonne":["Stato","Cosa vuol dire"],"righe":[["In lavorazione / Non approvato","Link inviato e ancora valido: il cliente non ha ancora confermato."],["Lavorato / Approvato","Il cliente ha confermato: CCQ Digital firmata."],["Invalidato","Link scaduto o cliente che chiede di essere ricontattato. <strong>Non \00e8 un KO</strong>: parte la CCQ standard (FAST, poi tradizionale)."]]}]'::jsonb, 'sync', TRUE, 12);
INSERT INTO procedura (id, brand, titolo, sottotitolo, etichetta, keywords, tipo, risposta, url, blocchi, origine, attiva, sort_order) VALUES (
  'sorgenia:space', 'sorgenia', 'Controlli su SPACE e KO', U&'Cosa viene verificato dopo la firma e perch\00e9 un contratto pu\00f2 saltare.', 'Dopo la firma',
  U&'controlli, space, viene, verificato, dopo, firma, perch\00e9, contratto, saltare, sistema, accettato, andare', 'blocchi', '', '', U&'[{"tipo":"tabella","titolo":"Controlli di sistema su SPACE","colonne":["Controllo","Ufficio che lo gestisce"],"righe":[["Credit check","Supporto Operation"],["Controllo carta","Gestione Contratti"],["CCQ: se la FAST CCQ \00e8 OK la pratica va in \201cAccettato\201d; se \00e8 KO la CCQ va organizzata","Supporto CCQ"]]},{"tipo":"lista","titolo":"Quando un contratto \201cAccettato\201d pu\00f2 andare in KO","voci":["<strong>Switch ricorrente</strong>: ammessi meno di 3 cambi di fornitore negli ultimi 12 mesi per il business, meno di 2 per il residenziale.","<strong>Morosit\00e0 verso il distributore</strong>: distacco per morosit\00e0 o CMOR.","<strong>Switch prevalente</strong> di un altro fornitore sullo stesso punto.","<strong>Disallineamento SDD</strong>: domiciliazione bancaria non allineata."]},{"tipo":"info","testo":"Contendibilit\00e0 di contatori, POD e PDR, stato delle riattivazioni e contratti in KO: scrivi o chiama la <strong>Gestione Contratti</strong> per i Mass Market, la <strong>Gestione PMI</strong> per le PMI."}]'::jsonb, 'sync', TRUE, 13);
INSERT INTO procedura (id, brand, titolo, sottotitolo, etichetta, keywords, tipo, risposta, url, blocchi, origine, attiva, sort_order) VALUES (
  'sorgenia:pa', 'sorgenia', 'Pubblica Amministrazione', 'Fatturazione elettronica, split payment e CIG per enti e comuni.', 'Enti',
  'pubblica, amministrazione, fatturazione, elettronica, split, payment, enti, comuni, compila, modulo, 2025', 'blocchi', '', '', U&'[{"tipo":"info","testo":"L\2019istanza va compilata <strong>solo se il cliente ha diritto</strong> alla fatturazione elettronica (art. 1 L. 244/2007) e/o allo split payment (art. 17-ter DPR 633/72)."},{"tipo":"passi","titolo":"Come si compila","voci":["Dati dell\2019ente: denominazione, sede legale, codice fiscale, P. IVA, telefono, e-mail o PEC e codice contratto Sorgenia.","Indica S\00cc o NO per <strong>codice CIG</strong>, <strong>fatturazione elettronica</strong> e <strong>split payment</strong>.","Dati del rappresentante legale o negoziale che firma.","<strong>Allegato 1</strong>: per ogni POD o PDR indica codice IPA, codice ufficio, codice univoco ufficio, tipologia (illuminazione pubblica, altri usi, altro), CIG e periodo di riferimento del CIG.","Luogo, data, <strong>timbro e firma</strong> del cliente."]},{"tipo":"nota","testo":"Senza questi dati, anche se l\2019ente li possiede, Sorgenia non applica la fatturazione elettronica n\00e9 lo split payment."},{"tipo":"file","titolo":"Modulo split payment 2025","testo":"Istanza fatturazione elettronica e split payment con Allegato 1 \00b7 PDF, 2 pagine","href":"assets/moduli/modulo-split-payment-2025.pdf"}]'::jsonb, 'sync', TRUE, 14);
INSERT INTO procedura (id, brand, titolo, sottotitolo, etichetta, keywords, tipo, risposta, url, blocchi, origine, attiva, sort_order) VALUES (
  'sorgenia:come-leggere', 'sorgenia', 'Come leggere le offerte Sorgenia', '', 'Offerte',
  'leggere, offerta, prezzo, spread, commercializzazione, sconto, lordo, netto, perdite, evoluzione, automatica, quota, variabile, solo', 'blocchi', '', '', U&'[{"tipo":"info","titolo":"Fee","testo":"\00c8 lo spread di Sorgenia sulla materia prima, in \20ac/kWh per la luce e in \20ac/Smc per il gas. Si somma all\2019indice (PUN o PSV): pi\00f9 la Fee \00e8 bassa, pi\00f9 l\2019offerta \00e8 competitiva."},{"tipo":"info","titolo":"Lordo o netto perdite","testo":"Sulle offerte luce business la CTE riporta due tabelle. La prima \00e8 <strong>al lordo delle perdite di rete</strong> (10% in bassa tensione), la seconda al netto. In fattura le perdite sul PUN sono indicate separatamente."},{"tipo":"info","titolo":"Evoluzione automatica","testo":"Le offerte variabili bloccano la Fee per 12 mesi: <strong>dal 13\00b0 mese la Fee aumenta</strong> al valore gi\00e0 scritto in CTE. Le offerte a prezzo fisso restano bloccate 24 mesi e dal 25\00b0 mese passano a un prezzo indicizzato. Dillo al cliente in fase di firma: \00e8 la prima causa di reclamo."},{"tipo":"info","titolo":"Quota di commercializzazione","testo":"\00c8 il costo fisso annuo per POD o PDR, indipendente dai consumi. In scheda \00e8 indicato anche l\2019equivalente mensile per farlo capire subito al cliente."},{"tipo":"info","titolo":"Quota variabile (solo gas business)","testo":"Su Impresa Gas Smart c\2019\00e8 anche un corrispettivo commerciale variabile di 0,00794 \20ac/Smc che si somma alla Fee."},{"tipo":"info","titolo":"Validit\00e0 della CTE","testo":"La data di scadenza \00e8 quella entro cui il contratto va <strong>firmato</strong>. Dopo quella data serve la CTE nuova, anche se il cliente aveva gi\00e0 visto il preventivo."}]'::jsonb, 'sync', TRUE, 15);
INSERT INTO procedura (id, brand, titolo, sottotitolo, etichetta, keywords, tipo, risposta, url, blocchi, origine, attiva, sort_order) VALUES (
  'sorgenia:portali', 'sorgenia', 'Portali e strumenti Sorgenia', '', 'Accessi',
  'portale, accesso, link, strumenti, comparatore, inserimento, apparound, verifica, creditizia', 'blocchi', '', '', U&'[{"tipo":"link","titolo":"Apparound","testo":"Portale di inserimento contratti Sorgenia.","href":"https://login.apparound.com/?source=webclient"},{"tipo":"link","titolo":"CRI \00b7 Verifica creditizia","testo":"Dynamic Rating: controllo del merito creditizio della partita IVA prima di caricare il contratto business.","href":"https://sorgenia-dynamic-rating.moxoff.it/auth/realms/sorgenia/protocol/openid-connect/auth?client_id=sorgenia-client&redirect_uri=https%3A%2F%2Fsorgenia-dynamic-rating.moxoff.it%2Foutput%23iss%3Dhttps%253A%252F%252Fsorgenia-dynamic-rating.moxoff.it%252Fauth%252Frealms%252Fsorgenia&state=b970c0c2-55c8-4d00-b8c5-caa9a339b7aa&response_mode=fragment&response_type=code&scope=openid&nonce=b5c1fa12-3ddc-440d-8a9d-23de5984222c"},{"tipo":"link","titolo":"Comparatore Sorgenia","testo":"Confronto bolletta e classifica delle offerte per risparmio, con preventivo PDF e invio WhatsApp.","href":"https://comparatoresorgenia.vercel.app"}]'::jsonb, 'sync', TRUE, 16);
INSERT INTO procedura (id, brand, titolo, sottotitolo, etichetta, keywords, tipo, risposta, url, blocchi, origine, attiva, sort_order) VALUES (
  'alperia:primo-accesso-al-portale-alper', 'alperia', 'Primo accesso al portale Alperia', 'Partner.Cloud - wall.alperia.eu', '',
  'primo, accesso, portale, partner, cloud, wall, crea, password, attiva, codice, sicurezza, tutte, volte, successive', 'blocchi', '', '', '[{"titolo":"Crea la tua password","passi":["Apri il sito <strong>wall.alperia.eu/fwall</strong>.","Clicca sulla linguetta <strong>Utenti Esterni</strong>.","Clicca su <strong>Password dimenticata?</strong> e scrivi la mail con cui ti hanno abilitato.","Apri la mail che ricevi (guarda anche nello Spam) e clicca sul link per scegliere la password."]},{"titolo":"Attiva il codice di sicurezza (MFA)","passi":["Scarica sul telefono l''app <strong>Microsoft Authenticator</strong> (va bene anche Google Authenticator).","Entra nel portale con la tua email e la password appena creata.","Segui le istruzioni sullo schermo per collegare l''app al tuo profilo."],"nota":"Serve uno smartphone con internet: senza l''app non si entra nel portale."},{"titolo":"Tutte le volte successive","passi":["Inserisci email e password.","Apri l''app Authenticator sul telefono e copia il codice che vedi."]}]'::jsonb, 'sync', TRUE, 17);
INSERT INTO procedura (id, brand, titolo, sottotitolo, etichetta, keywords, tipo, risposta, url, blocchi, origine, attiva, sort_order) VALUES (
  'alperia:guida-iqc', 'alperia', 'Portale IQC: prenotare la check call', 'welcomecall.it/qcmobile', '',
  'portale, prenotare, check, call, welcomecall, qcmobile, primo, accesso, dati, cliente, contratto, esempi, pratici', 'blocchi', '', '', U&'[{"titolo":"Primo accesso","passi":["Entra su <strong>welcomecall.it/qcmobile</strong>.","Il tuo <strong>username</strong> \00e8 il codice agente e la prima password \00e8 uguale allo username.","Clicca <strong>Cambio Password</strong>, scegli la nuova password e clicca <strong>Salva</strong>."],"nota":"Chi coordina la rete pu\00f2 chiedere un profilo Responsabile/Back office su welcomecall.it/qcagenzie per vedere gli esiti di tutti i contratti.","azione":{"testo":"Qual \00e8 il mio username?","tipo":"username"}},{"titolo":"Dati del cliente","passi":["Scegli se il cliente \00e8 <strong>domestico</strong> (persona fisica) o <strong>business</strong> (persona giuridica).","Se \00e8 business scrivi anche nome e cognome del legale rappresentante: sar\00e0 lui a rispondere alla chiamata.","Inserisci luogo, data di nascita e sesso: il codice fiscale si scrive da solo (se lo cambi premi <strong>Ricalcola</strong>).","Telefono ed email sono obbligatori e devono essere <strong>identici</strong> a quelli scritti sul contratto."],"nota":"Il campo Voltura non si pu\00f2 usare e la Delega non \00e8 consentita."},{"titolo":"Dati del contratto","passi":["Indica quanti contratti con codice proposta diverso ha firmato il cliente (di solito 1).","Controlla la data firma: \00e8 gi\00e0 scritta con la data di oggi, cambiala se il cliente ha firmato prima.","Numero modulo di adesione: clicca <strong>manuale</strong> e copia il numero per i contratti cartacei; con il PDF compilabile senza numero clicca <strong>calcola</strong>.","Segmento: <strong>residenziale</strong> per la persona fisica, <strong>microbusiness</strong> per la persona giuridica.","Fornitore uscente e POD/PDR non sono obbligatori, ma e meglio inserirli.","Indica il tipo di servizio (luce e/o gas) e quanti contatori ci sono in ogni contratto.","Clicca <strong>Salva e continua</strong>: la chiamata parte di solito entro 20 minuti."]},{"titolo":"Esempi pratici","passi":["1 contratto con 2 contatori luce: contratti <strong>1</strong>, servizi luce <strong>2</strong>.","1 contratto dual con 1 luce e 1 gas: contratti <strong>1</strong>, servizi luce <strong>1</strong> e gas <strong>1</strong>.","Stesso cliente con 1 contratto business (3 contatori luce) e 1 domestico (1 luce e 1 gas): scegli persona giuridica, metti contratti <strong>2</strong>, inserisci il primo e poi clicca <strong>inserisci nuovo contratto stesso cliente</strong>."]}]'::jsonb, 'sync', TRUE, 18);
INSERT INTO procedura (id, brand, titolo, sottotitolo, etichetta, keywords, tipo, risposta, url, blocchi, origine, attiva, sort_order) VALUES (
  'alperia:scheda-voltura', 'alperia', 'Voltura', '', 'Operazioni',
  'voltura, operazioni', 'blocchi', '', '', U&'[{"tipo":"info","titolo":"Voltura","testo":"Il contatore \00e8 attivo e cambia solo l''intestatario."},{"tipo":"lista","titolo":"Nel dettaglio","voci":[{"titolo":"Cosa serve","voci":["Dati del nuovo intestatario: nome, codice fiscale, telefono ed e-mail.","Codice <strong>POD</strong> per la luce o <strong>PDR</strong> per il gas, con l''indirizzo della fornitura.","Dati del precedente intestatario: nome o ragione sociale e codice fiscale o partita IVA.","Numero della proposta, data e firma del cliente."]},{"titolo":"Tempi massimi ARERA","voci":["Luce: <strong>5 giorni lavorativi</strong> in tutto \2014 3 giorni al venditore per accettare la richiesta completa e 2 per registrare il nuovo contratto.","Gas: <strong>4 giorni lavorativi</strong> in tutto \2014 2 giorni per l''accettazione del venditore e 2 per la registrazione del contratto.","I giorni partono da quando la richiesta \00e8 <strong>completa</strong>: se mancano dati o allegati il conteggio non parte."]},{"titolo":"Da scegliere sul modulo","voci":["Privato: voltura <strong>ordinaria</strong> oppure <strong>mortis causa</strong>.","Business gas: voltura <strong>ordinaria</strong> oppure <strong>per incorporazione</strong>."]},{"titolo":"Costi","voci":["Luce: oltre alle spese del distributore pu\00f2 essere applicato un contributo di vendita di <strong>23,00 \20ac + IVA</strong> e/o marca da bollo.","Gas: vengono addebitati i costi del distributore (delibera 367/2014/R/gas)."]}]}]'::jsonb, 'sync', TRUE, 19);
INSERT INTO procedura (id, brand, titolo, sottotitolo, etichetta, keywords, tipo, risposta, url, blocchi, origine, attiva, sort_order) VALUES (
  'alperia:scheda-subentro', 'alperia', 'Subentro', '', 'Operazioni',
  'subentro, operazioni', 'blocchi', '', '', U&'[{"tipo":"info","titolo":"Subentro","testo":"Il contatore \00e8 chiuso e va riattivato per il nuovo cliente."},{"tipo":"lista","titolo":"Nel dettaglio","voci":[{"titolo":"Cosa serve","voci":["Dati del cliente, codice <strong>POD</strong> o <strong>PDR</strong> e indirizzo della fornitura.","Luce: potenza impegnata e disponibile in kW, tensione (monofase 220 V o trifase 380 V) e tipologia di contratto (domestico residente, non residente, altri usi).","Gas: potenzialit\00e0 massima richiesta in kW; per il business anche la tipologia (condominio uso domestico, commercio e servizi, industria, servizio pubblico).","Luce: indicare se il subentro \00e8 <strong>a parit\00e0 di condizioni di connessione</strong> o <strong>con modifica</strong>."]},{"titolo":"Tempi massimi ARERA","voci":["Luce: <strong>2 giorni lavorativi</strong> al venditore per mandare la richiesta al distributore, pi\00f9 <strong>5 giorni lavorativi</strong> al distributore per attivare.","Gas: <strong>2 giorni lavorativi</strong> al venditore pi\00f9 <strong>10 giorni lavorativi</strong> al distributore.","Gas con modifiche all''impianto: i 10 giorni partono da quando il distributore riceve tutta la documentazione di sicurezza.","Se il distributore sfora, il cliente riceve un <strong>indennizzo automatico in bolletta</strong>."]},{"titolo":"Costi","voci":["Luce: contributo di vendita di <strong>23,00 \20ac + IVA</strong> e/o marca da bollo, oltre alle spese del distributore.","Gas privato: contributo di vendita di <strong>30,00 \20ac + IVA</strong> e/o marca da bollo.","Gas business: costi del distributore secondo la delibera 367/2014/R/gas."]},{"titolo":"Attenzione","voci":["L''importo del modulo \00e8 un preventivo: se dopo i controlli il distributore lo cambia, Alperia avvisa il cliente per farglielo accettare."]}]}]'::jsonb, 'sync', TRUE, 20);
INSERT INTO procedura (id, brand, titolo, sottotitolo, etichetta, keywords, tipo, risposta, url, blocchi, origine, attiva, sort_order) VALUES (
  'alperia:scheda-attivazione', 'alperia', 'Nuova attivazione', '', 'Operazioni',
  'nuova, attivazione, operazioni', 'blocchi', '', '', U&'[{"tipo":"info","titolo":"Nuova attivazione","testo":"Il contatore c''\00e8 gi\00e0 ed \00e8 allacciato, ma non \00e8 mai stato attivato."},{"tipo":"lista","titolo":"Nel dettaglio","voci":[{"titolo":"Cosa serve","voci":["Dati del cliente, codice <strong>POD</strong> o <strong>PDR</strong> e indirizzo della fornitura.","Luce: potenza impegnata e disponibile, tensione/fase, tipologia di contratto e se l''attivazione \00e8 a parit\00e0 di condizioni di connessione o con modifica.","Gas: potenzialit\00e0 massima in kW, <strong>categoria d''uso</strong> (riscaldamento, cottura cibi, acqua calda sanitaria), consumo annuo in Smc e nome del distributore."]},{"titolo":"Tempi massimi ARERA","voci":["Luce: <strong>2 giorni lavorativi</strong> al venditore pi\00f9 <strong>5 giorni lavorativi</strong> al distributore dalla richiesta completa.","Gas: <strong>2 giorni lavorativi</strong> al venditore pi\00f9 <strong>10 giorni lavorativi</strong> al distributore.","Gas su impianti nuovi o modificati: il conteggio parte da quando arriva la documentazione per l''accertamento della sicurezza (allegati I/40 e H/40).","Se il contatore non \00e8 ancora allacciato valgono invece i tempi dell''allacciamento."]},{"titolo":"Costi","voci":["Luce: contributo di vendita di <strong>23,00 \20ac + IVA</strong> e/o marca da bollo, oltre alle spese del distributore.","Gas: costi del distributore secondo la delibera 367/2014/R/gas."]},{"titolo":"Attenzione","voci":["Per il gas servono quasi sempre gli allegati <strong>H/40</strong> e <strong>I/40</strong>: li trovi in fondo, tra gli allegati.","Luce: se sul punto c''\00e8 una morosit\00e0 pregressa, l''attivazione resta sospesa finch\00e9 il debito non viene saldato."]}]}]'::jsonb, 'sync', TRUE, 21);
INSERT INTO procedura (id, brand, titolo, sottotitolo, etichetta, keywords, tipo, risposta, url, blocchi, origine, attiva, sort_order) VALUES (
  'alperia:scheda-connessione', 'alperia', 'Nuova connessione e allaccio', '', 'Operazioni',
  'nuova, connessione, allaccio, operazioni', 'blocchi', '', '', U&'[{"tipo":"info","titolo":"Nuova connessione e allaccio","testo":"Il contatore non c''\00e8 ancora: serve prima l''allacciamento alla rete."},{"tipo":"lista","titolo":"Nel dettaglio","voci":[{"titolo":"Cosa serve","voci":["Luce: indirizzo, potenza impegnata e disponibile, tensione/fase, tipologia di contratto, tipo di connessione (<strong>ordinaria permanente</strong> o <strong>temporanea</strong> con il periodo) e se i lavori vanno fatti fuori orario di lavoro.","Gas: indirizzo, potenzialit\00e0 massima in kW, categoria d''uso, consumo annuo in Smc e <strong>numero di contatori da installare</strong>."]},{"titolo":"Tempi del distributore (luce)","voci":["Preventivo: <strong>15 giorni lavorativi</strong>.","Lavori semplici: <strong>10 giorni lavorativi</strong>.","Lavori complessi sulla rete: <strong>50 giorni lavorativi</strong>.","Attivazione della fornitura: <strong>5 giorni lavorativi</strong>."]},{"titolo":"Tempi del distributore (gas)","voci":["Preventivo: <strong>15 giorni lavorativi</strong> (30 se i lavori sono complessi).","Lavori semplici in bassa pressione: <strong>10 giorni lavorativi</strong>.","Attivazione della fornitura: <strong>10 giorni lavorativi</strong>."]},{"titolo":"Costi","voci":["Luce: contributi a forfait per il distributore (delibera 654/2015/R/eel) pi\00f9 l''eventuale contributo di vendita di <strong>23,00 \20ac + IVA</strong> e/o marca da bollo.","Gas: costi del distributore in base alla prestazione richiesta."]}]}]'::jsonb, 'sync', TRUE, 22);
INSERT INTO procedura (id, brand, titolo, sottotitolo, etichetta, keywords, tipo, risposta, url, blocchi, origine, attiva, sort_order) VALUES (
  'alperia:scheda-lavori', 'alperia', 'Lavori sul contatore', '', 'Operazioni',
  'lavori, contatore, operazioni', 'blocchi', '', '', U&'[{"tipo":"info","titolo":"Lavori sul contatore","testo":"Richieste di spostamento del gruppo di misura."},{"tipo":"lista","titolo":"Nel dettaglio","voci":[{"titolo":"Cosa serve","voci":["Codice cliente, dati dell''intestatario (per le aziende anche ragione sociale, partita IVA e chi rappresenta la societ\00e0).","Codice <strong>POD</strong> e indirizzo della fornitura."]},{"titolo":"Tempi e costi","voci":["Esecuzione entro <strong>10 giorni lavorativi</strong> dall''accettazione del preventivo del distributore.","Contributo previsto: <strong>222,58 \20ac</strong>."]},{"titolo":"Attenzione","voci":["Lo spostamento deve restare entro <strong>10 metri</strong> dalla posizione attuale del contatore.","Dopo il sopralluogo il distributore pu\00f2 chiedere lavori a carico del cliente."]}]}]'::jsonb, 'sync', TRUE, 23);
INSERT INTO procedura (id, brand, titolo, sottotitolo, etichetta, keywords, tipo, risposta, url, blocchi, origine, attiva, sort_order) VALUES (
  'alperia:scheda-allegati', 'alperia', 'Allegati e dichiarazioni', '', 'Operazioni',
  'allegati, dichiarazioni, operazioni', 'blocchi', '', '', U&'[{"tipo":"info","titolo":"Allegati e dichiarazioni","testo":"Documenti da allegare alla pratica quando vengono richiesti."},{"tipo":"lista","titolo":"Nel dettaglio","voci":[{"titolo":"Allegato H/40 (gas)","voci":["\00c8 la conferma del cliente finale alla richiesta di attivazione o riattivazione del gas (delibera 40/2014/R/gas).","Una parte la compila il venditore (PDR, codice della richiesta, recapito del distributore), il resto lo compila e firma il cliente."]},{"titolo":"Allegato I/40 (gas)","voci":["\00c8 l''attestazione di corretta esecuzione dell''impianto: la compila e firma <strong>l''installatore</strong>, non il cliente."]},{"titolo":"Istanza regolarit\00e0 edilizia","voci":["Dichiarazione sostitutiva prevista dal D.P.R. 380/2001: senza, o se compilata male, <strong>il contratto di fornitura non si perfeziona ed \00e8 nullo</strong>.","Va firmata dal richiedente e accompagnata dalla copia dell''intero documento d''identit\00e0; viene poi inoltrata al Comune.","Scegli la versione giusta: usi domestici, altri usi, cantiere o uso temporaneo, con la variante Sicilia dove prevista."]}]}]'::jsonb, 'sync', TRUE, 24);
INSERT INTO procedura (id, brand, titolo, sottotitolo, etichetta, keywords, tipo, risposta, url, blocchi, origine, attiva, sort_order) VALUES (
  'alperia:script-checkcall', 'alperia', 'La chiamata che riceve il cliente', '', 'Check call',
  'chiamata, riceve, cliente, check, call', 'blocchi', '', '', U&'[{"tipo":"info","titolo":"In sintesi","testo":"Dopo la prenotazione un operatore di Escon chiama il cliente per conto di Alperia. Se il cliente sa cosa aspettarsi, la chiamata va a buon fine."},{"tipo":"lista","titolo":"Numeri da cui chiama","voci":[{"etichetta":"Numero che chiama","valore":"0471 1431251"},{"etichetta":"In rari casi","valore":"06 98240767"},{"etichetta":"Tempo di attesa","valore":"circa 20 minuti"}]},{"tipo":"lista","titolo":"Prima della chiamata","voci":["Avvisa il cliente: ricever\00e0 una chiamata da questi numeri, non \00e8 pubblicit\00e0.","Deve rispondere <strong>l''intestatario del contratto</strong> (per le aziende il legale rappresentante): familiari o delegati non vanno bene.","La telefonata viene registrata e all''inizio l''operatore chiede il permesso.","Ricorda al cliente la data della firma, quante forniture ha attivato e il fornitore che sta lasciando."]},{"tipo":"lista","titolo":"Cosa chiedono al cliente","voci":["Nome, cognome, luogo e data di nascita.","Conferma di essere l''intestatario del contratto (o il legale rappresentante della societ\00e0).","Conferma della data e dell''ora di oggi.","Conferma del numero di telefono su cui sta parlando.","Conferma di aver firmato la richiesta di fornitura Alperia e per quante utenze luce/gas.","Conferma di voler cambiare fornitore e di sapere che le fatture arriveranno da Alperia.","Voto da 1 a 5 sul servizio del consulente (5 \00e8 il massimo)."]},{"tipo":"nota","testo":"Se il cliente <strong>non autorizza la registrazione</strong>, la check call ha esito negativo e la fornitura non viene attivata. Se il cliente in quel momento non pu\00f2 parlare, l''operatore chiede quando richiamare: fatti dire dal cliente la fascia oraria migliore. Se risponde una persona diversa dall''intestatario, la chiamata viene riprogrammata."}]'::jsonb, 'sync', TRUE, 25);
INSERT INTO procedura (id, brand, titolo, sottotitolo, etichetta, keywords, tipo, risposta, url, blocchi, origine, attiva, sort_order) VALUES (
  'alperia:come-leggere', 'alperia', 'Come leggere le offerte Alperia', '', 'Offerte',
  'leggere, offerta, prezzo, spread, commercializzazione, sconto, variabile, fisso, voci, sempre, presenti, giro, completo, vendita', 'blocchi', '', '', U&'[{"tipo":"info","titolo":"Prezzo variabile","testo":"<strong>Luce:</strong> PUN + lo spread indicato, per ogni kWh consumato. \00b7 <strong>Gas:</strong> PSV + lo spread indicato, per ogni Sm&sup3; consumato. \00b7 PUN e PSV cambiano ogni mese: li trovi gi\00e0 aggiornati dentro il comparatore. \00b7 Alcune offerte hanno uno spread diverso dal secondo anno: lo trovi scritto sotto il prezzo."},{"tipo":"info","titolo":"Prezzo fisso","testo":"Il costo unitario resta <strong>bloccato</strong> per tutta la durata del contratto. \00b7 Nessuna sorpresa in bolletta se il mercato sale. \00b7 Ideale per chi vuole spendere sempre la stessa cifra."},{"tipo":"info","titolo":"Voci sempre presenti","testo":"<strong>Costo unitario:</strong> il prezzo della materia prima luce o gas. \00b7 <strong>Commercializzazione:</strong> quota fissa per ogni fornitura. \00c8 indicata all''anno, con sotto l''equivalente al mese. \00b7 <strong>Dettagli e utilizzi:</strong> nella scheda apri il riquadro per vedere quota del 2\00b0 e 3\00b0 anno, QAC, gas verde e quali operazioni sono ammesse. \00b7 Restano fuori trasporto, oneri di sistema e imposte: sono uguali per tutti i fornitori."},{"tipo":"info","titolo":"Il giro completo della vendita","testo":"1. Analizzi la bolletta con il <strong>comparatore</strong>. \00b7 2. Carichi il contratto sul <strong>portale inserimento</strong>. \00b7 3. Prenoti la <strong>check call</strong> sul portale IQC. \00b7 4. Il cliente riceve la chiamata e conferma i dati."}]'::jsonb, 'sync', TRUE, 26);
INSERT INTO procedura (id, brand, titolo, sottotitolo, etichetta, keywords, tipo, risposta, url, blocchi, origine, attiva, sort_order) VALUES (
  'alperia:portali', 'alperia', 'Portali e strumenti Alperia', '', 'Accessi',
  'portale, accesso, link, strumenti, comparatore, inserimento, check, call', 'blocchi', '', '', U&'[{"tipo":"link","titolo":"Portale inserimento","testo":"Caricamento contratti luce e gas sul Wall Alperia.","href":"https://wall.alperia.eu/fwall/#/fwall/authentication/login/756fb9ca-a244-1d5c-4d94-a5dd83bbfb73/login-page"},{"tipo":"link","titolo":"Portale check call","testo":"Prenota la chiamata di qualit\00e0 e controlla gli esiti.","href":"https://www.welcomecall.it/QcMobile/#/"},{"tipo":"link","titolo":"Comparatore Alperia","testo":"Analizza la bolletta del cliente, con PUN e PSV sempre aggiornati.","href":"https://alperiae2k.vercel.app/"}]'::jsonb, 'sync', TRUE, 27);
INSERT INTO procedura (id, brand, titolo, sottotitolo, etichetta, keywords, tipo, risposta, url, blocchi, origine, attiva, sort_order) VALUES (
  'alperia:modulistica', 'alperia', 'Modulistica Alperia', '', 'Moduli',
  'modulo, moduli, modulistica, allegato, allegati, stampare, firmare, documento', 'blocchi', '', '', U&'[{"tipo":"tabella","titolo":"Voltura","colonne":["Modulo","Per","Formato"],"righe":[["Voltura luce","luce \00b7 privato","PDF"],["Voltura luce","luce \00b7 business","PDF"],["Voltura gas","gas \00b7 privato","PDF"],["Voltura gas","gas \00b7 business","PDF"]]},{"tipo":"tabella","titolo":"Subentro","colonne":["Modulo","Per","Formato"],"righe":[["Subentro luce","luce \00b7 privato","PDF"],["Subentro luce","luce \00b7 business","PDF"],["Subentro gas","gas \00b7 privato","PDF"],["Subentro gas","gas \00b7 business","PDF"]]},{"tipo":"tabella","titolo":"Connessione","colonne":["Modulo","Per","Formato"],"righe":[["Nuova connessione con attivazione luce","luce \00b7 privato","PDF"],["Nuova connessione con attivazione luce","luce \00b7 business","PDF"],["Posa con allaccio gas","gas \00b7 privato","PDF"],["Posa con allaccio gas","gas \00b7 business","PDF"]]},{"tipo":"tabella","titolo":"Attivazione","colonne":["Modulo","Per","Formato"],"righe":[["Nuova attivazione luce","luce \00b7 privato","PDF"],["Nuova attivazione luce","luce \00b7 business","PDF"],["Nuova attivazione gas","gas \00b7 privato","PDF"],["Nuova attivazione gas","gas \00b7 business","PDF"]]},{"tipo":"tabella","titolo":"Lavori","colonne":["Modulo","Per","Formato"],"righe":[["Spostamento gruppo di misura luce","luce","PDF"]]},{"tipo":"tabella","titolo":"Allegati","colonne":["Modulo","Per","Formato"],"righe":[["Istanza regolarit\00e0 edilizia \00b7 usi domestici","privato","DOC"],["Istanza regolarit\00e0 edilizia \00b7 usi domestici (Sicilia)","privato","DOC"],["Istanza regolarit\00e0 edilizia \00b7 altri usi","business","DOC"],["Istanza regolarit\00e0 edilizia \00b7 altri usi (Sicilia)","business","DOC"],["Istanza regolarit\00e0 edilizia \00b7 cantiere","business","DOC"],["Istanza regolarit\00e0 edilizia \00b7 uso temporaneo","business","DOC"],["Allegato H/40","gas","PDF"],["Allegato I/40 \00b7 corretta esecuzione impianto","gas","PDF"]]}]'::jsonb, 'sync', TRUE, 28);

